create or replace function private.supervisor_allowed() returns boolean language sql stable security definer set search_path='' as $$ select private.actor_org() is not null and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('teacher','supervisor')) and exists(select 1 from public.supervisor_assignments a left join public.supervisor_substitutions s on s.assignment_id=a.id and s.revoked_at is null and s.effective_from<=now() and (s.effective_until is null or s.effective_until>now()) where a.active and a.organization_id=private.actor_org() and coalesce(s.substitute_supervisor_id,a.original_supervisor_id)=auth.uid()) $$;
revoke all on function private.supervisor_allowed() from public,anon;
grant execute on function private.supervisor_allowed() to authenticated;
create or replace function public.has_supervisor_context() returns boolean language sql stable security invoker set search_path='' as $$ select private.supervisor_allowed() $$;
create or replace function private.validate_assignment() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='teacher_assignments' then if not exists(select 1 from public.profiles where id=new.teacher_id and organization_id=new.organization_id and role='teacher' and active) then raise exception 'Invalid teacher'; end if; elsif tg_table_name='student_enrollments' then if not exists(select 1 from public.profiles where id=new.student_id and organization_id=new.organization_id and role='student' and active) then raise exception 'Invalid student'; end if; elsif tg_table_name='supervisor_assignments' then if not exists(select 1 from public.profiles where id=new.original_supervisor_id and organization_id=new.organization_id and role in ('teacher','supervisor') and active) then raise exception 'Invalid supervisor'; end if; elsif tg_table_name='supervisor_substitutions' then if not exists(select 1 from public.profiles p join public.supervisor_assignments a on a.id=new.assignment_id where p.id=new.substitute_supervisor_id and p.organization_id=a.organization_id and p.role in ('teacher','supervisor') and p.active) then raise exception 'Invalid substitute'; end if; end if; return new; end $$;
revoke all on function private.validate_assignment() from public,anon,authenticated;
do $$ declare t text; begin foreach t in array array['teacher_assignments','student_enrollments','supervisor_assignments','supervisor_substitutions'] loop execute format('create trigger validate_assignment before insert or update on public.%I for each row execute function private.validate_assignment()',t); end loop; end $$;
